BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'obgyn-malignancies' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic obgyn-malignancies not found.';
    END IF;

    -- Batch 7: 336-370 (Advanced Clinical Vignettes — Cervical, Uterine, Ovarian)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- ===== CERVICAL CANCER — ADVANCED =====
    (v_topic_id, '336: A 32-year-old woman with Stage IB1 cervical cancer (2.5 cm tumor, squamous) desires future fertility. Which procedure allows fertility preservation?', '["Radical Hysterectomy", "Radical Trachelectomy with pelvic lymphadenectomy", "Simple cervical conization", "Radiation alone"]', 1, 'Radical trachelectomy removes the cervix and parametria while leaving the uterine body, preserving fertility in select patients with tumors ≤ 2 cm and no lymph node involvement. (Williams; Beckmann)'),

    (v_topic_id, '337: Intraoperative frozen section during radical hysterectomy reveals a positive pelvic lymph node. What is the MOST appropriate next step?', '["Complete the radical hysterectomy and add postoperative radiation", "Abort surgery and proceed with definitive chemoradiation only", "Perform para-aortic dissection only", "Add chemotherapy intraoperatively"]', 1, 'Current evidence supports aborting the radical hysterectomy once nodal metastasis is confirmed intraoperatively, then delivering definitive concurrent chemoradiation to avoid combined therapy morbidity (double treatment toxicity). (Comprehensive Gynecology; ACOG)'),

    (v_topic_id, '338: A 55-year-old woman with Stage IIIB cervical cancer completes chemoradiation. Six months later, CT shows a 2 cm central pelvic mass with no distant metastasis. What is the BEST option?', '["Repeat chemoradiation", "Pelvic Exenteration (if disease is central and surgically resectable)", "Palliative chemotherapy only", "Hospice"]', 1, 'Central pelvic recurrence after radiation without sidewall or distant disease is the classic indication for pelvic exenteration (anterior, posterior, or total). (Williams; Blueprints OB/GYN)'),

    (v_topic_id, '339: Which of the following is the MOST reliable indicator of parametrial invasion on physical exam staging in cervical cancer?', '["Tumor size on speculum exam", "Rectovaginal exam revealing induration extending to the pelvic sidewall", "CT scan finding", "Cystoscopy finding"]', 1, 'Parametrial involvement is best assessed by bimanual/rectovaginal examination, which defines clinical Stage IIB vs IB/IIA. (Williams; Case Files OB/GYN)'),

    (v_topic_id, '340: A 24-year-old woman''s Pap smear shows "AGC — favor neoplastic." What is the NEXT best step?', '["Repeat Pap in 6 months", "Colposcopy, endocervical curettage (ECC), AND endometrial biopsy (if ≥ 35 or risk factors)", "HPV testing only", "Immediate LEEP"]', 1, 'AGC-favor neoplastic is a high-risk result requiring comprehensive evaluation of both the cervix and the endometrium. (ACOG; Blueprints OB/GYN)'),

    (v_topic_id, '341: A patient with cervical cancer receives external beam radiation to the pelvis followed by intracavitary brachytherapy. What is the main ADVANTAGE of brachytherapy?', '["It avoids all side effects", "It delivers a high local dose to the tumor while minimizing radiation to adjacent bladder and rectum", "It replaces external beam therapy", "It is used only for Stage IV disease"]', 1, 'Brachytherapy uses intracavitary devices (tandem and ring/ovoids) to deliver concentrated radiation close to the cervical tumor, sparing nearby structures. (Williams; Comprehensive Gynecology)'),

    (v_topic_id, '342: A 38-year-old woman with a prior LEEP for CIN 3 presents with a new HSIL Pap and colposcopy shows a 3 mm lesion in the canal that cannot be fully visualized. Next step?', '["Repeat LEEP", "Cold Knife Conization (CKC) for adequate endocervical margin assessment", "Hysterectomy immediately", "HPV test only"]', 1, 'If the lesion is not fully visualized (unsatisfactory colposcopy), or after a prior excisional procedure, CKC is preferred to adequately assess surgical margins and rule out invasion. (ACOG; Beckmann)'),

    -- ===== ENDOMETRIAL / UTERINE CANCER — ADVANCED =====
    (v_topic_id, '343: A 67-year-old woman has Stage IIIA endometrial cancer (Grade 2, endometrioid type) found to have ovarian involvement at surgery. What adjuvant therapy is recommended?', '["Observation", "Vaginal brachytherapy alone", "External beam pelvic radiation ± chemotherapy (carboplatin/paclitaxel)", "Tamoxifen only"]', 2, 'Stage III endometrial cancer with extrauterine spread requires adjuvant therapy; carboplatin/paclitaxel chemotherapy with or without radiation is the current standard. (ACOG; Comprehensive Gynecology)'),

    (v_topic_id, '344: A 52-year-old woman with morbid obesity (BMI 48), no vaginal bleeding, undergoes pelvic ultrasound for urinary complaints. Endometrial thickness is 6 mm. She is postmenopausal. What is the next step?', '["No further workup needed", "Endometrial Biopsy (EMB)", "MRI pelvis", "Laparoscopy"]', 1, 'Any endometrial thickness > 4 mm in a postmenopausal woman with bleeding OR > 4-5 mm incidentally found warrants EMB to rule out hyperplasia or cancer, especially with obesity as a risk factor. (ACOG; Williams)'),

    (v_topic_id, '345: A patient with endometrial cancer is found to have tumor cells in the peritoneal washings (positive cytology). Per the current FIGO 2023 staging revision, how is this classified?', '["Stage IVB", "It does not change stage on its own — it is reported separately but no longer automatically upstages", "Stage IIIA", "Stage IIA"]', 1, 'The 2023 FIGO staging revision for endometrial cancer changed the treatment of positive peritoneal cytology; it is now a separate notation and does not automatically upstage to IIIA if the only finding. (FIGO 2023; Comprehensive Gynecology)'),

    (v_topic_id, '346: A 70-year-old thin woman is diagnosed with Uterine Papillary Serous Carcinoma (UPSC) on EMB. Hysterectomy staging reveals no myometrial invasion and the tumor is confined to the endometrial polyp. What adjuvant therapy is STILL recommended?', '["None — Stage IA disease needs no treatment", "Vaginal brachytherapy only", "Chemotherapy (carboplatin/paclitaxel) ± radiation even for Stage IA UPSC", "Progestins only"]', 2, 'UPSC (Type II) has an aggressive biology and strong propensity for early peritoneal spread even from minimal invasion, so systemic chemotherapy ± radiation is recommended even in Stage IA. (Comprehensive Gynecology; ACOG)'),

    (v_topic_id, '347: A 45-year-old woman with endometrial cancer undergoes sentinel lymph node (SLN) mapping. What is the ADVANTAGE of SLN biopsy over full lymphadenectomy?', '["It is more accurate for cancer staging", "It reduces operative morbidity (lymphedema, lymphocele) while providing comparable staging information", "It is cheaper", "It detects more nodes"]', 1, 'SLN mapping (using ICG or blue dye) identifies the first draining node and avoids the morbidity of full pelvic lymph node dissection without sacrificing staging accuracy. (ACOG; Comprehensive Gynecology)'),

    (v_topic_id, '348: Which molecular/genomic subtype of endometrial cancer has the BEST prognosis?', '["p53-mutant (POLE-ultramutated)", "POLE-ultramutated", "Copy-number-high (serous-like)", "Mismatch Repair Deficient (dMMR)"]', 1, 'POLE-ultramutated endometrial cancers have an extremely high mutation burden and robust immune response, conferring the best prognosis among the four TCGA molecular subtypes. (Comprehensive Gynecology; ACOG)'),

    (v_topic_id, '349: A patient with mismatch repair deficient (dMMR) recurrent endometrial cancer fails carboplatin/paclitaxel. Which targeted therapy is MOST appropriate?', '["Bevacizumab", "Pembrolizumab (PD-1 immune checkpoint inhibitor)", "Cisplatin", "Tamoxifen"]', 1, 'Pembrolizumab (anti-PD-1) is FDA-approved for dMMR/MSI-H solid tumors including endometrial cancer with durable responses in recurrent disease. (ACOG; Comprehensive Gynecology)'),

    (v_topic_id, '350: A 48-year-old woman with uterine leiomyosarcoma undergoes hysterectomy. Which pre-operative procedure is NOW CONTRAINDICATED due to the risk of disseminating occult malignancy?', '["Hysteroscopy", "Power morcellation of the uterus", "Suction curettage", "MRI"]', 1, 'The FDA issued a black-box warning against power morcellation in premenopausal women undergoing hysterectomy/myomectomy for presumed fibroids because occult uterine sarcoma can be disseminated. (ACOG; FDA Advisory)'),

    (v_topic_id, '351: Which uterine sarcoma has the WORST prognosis?', '["Low-grade Endometrial Stromal Sarcoma (LG-ESS)", "Leiomyosarcoma", "Carcinosarcoma (MMMT)", "Adenosarcoma"]', 2, 'Carcinosarcoma (malignant mixed Müllerian tumor) contains both high-grade carcinomatous and sarcomatous elements and behaves like a high-grade carcinoma; it carries the worst prognosis. (Comprehensive Gynecology; Williams)'),

    -- ===== OVARIAN CANCER — ADVANCED =====
    (v_topic_id, '352: A woman with BRCA1 mutation is considering Risk-Reducing Salpingo-Oophorectomy (RRSO). After RRSO at age 40, what does she still need?', '["No further cancer surveillance", "Annual mammography and consideration of MRI for breast cancer surveillance", "Annual CA-125 screening for ovarian cancer", "Vaginal progesterone"]', 1, 'RRSO effectively eliminates ovarian cancer risk but does NOT eliminate the breast cancer risk from BRCA1 (though it reduces it). Ongoing breast surveillance is essential. (ACOG; Comprehensive Gynecology)'),

    (v_topic_id, '353: "Serous Tubal Intraepithelial Carcinoma" (STIC) is best described as:', '["Invasive ovarian cancer", "A non-invasive precursor lesion found in the fallopian tube fimbria that is the origin of most high-grade serous ovarian cancers", "A benign ovarian cyst", "A uterine lesion"]', 1, 'The modern understanding is that most high-grade serous ovarian cancers originate from STIC lesions in the distal fallopian tube, not the ovarian surface epithelium. (Comprehensive Gynecology; Beckmann)'),

    (v_topic_id, '354: A 22-year-old woman has a 15 cm ovarian mass. Tumor markers: AFP 8,000 ng/mL, hCG normal, LDH mildly elevated. Frozen section shows "Schiller-Duval bodies." Diagnosis?', '["Dysgerminoma", "Yolk Sac Tumor (Endodermal Sinus Tumor)", "Immature Teratoma", "Choriocarcinoma"]', 1, 'Markedly elevated AFP with Schiller-Duval bodies on pathology is the classic presentation of Yolk Sac Tumor (Endodermal Sinus Tumor). (Williams; Blueprints OB/GYN)'),

    (v_topic_id, '355: A 19-year-old has a rapidly enlarging 18 cm ovarian tumor. LDH is 5,000. Pathology shows "large cells with central nuclei and lymphocytic infiltrate." What chemotherapy regimen is MOST appropriate?', '["Carboplatin + Paclitaxel", "BEP (Bleomycin, Etoposide, Cisplatin)", "Methotrexate", "CHOP"]', 1, 'Dysgerminoma (analogous to seminoma) is treated with BEP chemotherapy for advanced stages; it is highly chemosensitive. (Williams; Comprehensive Gynecology)'),

    (v_topic_id, '356: A postmenopausal woman has a Stage IIIC ovarian cancer (high-grade serous). After optimal cytoreduction (no visible residual tumor), which intraperitoneal/systemic chemotherapy approach offers the BEST survival advantage?', '["IV carboplatin/paclitaxel alone", "IP (Intraperitoneal) cisplatin/paclitaxel + IV paclitaxel (GOG 172 regimen)", "IV doxorubicin alone", "Oral capecitabine"]', 1, 'GOG-172 demonstrated a significant overall survival advantage for intraperitoneal chemotherapy in optimally debulked Stage III ovarian cancer, though toxicity is higher. (ACOG; Comprehensive Gynecology)'),

    (v_topic_id, '357: A patient with BRCA2-mutated, platinum-sensitive recurrent ovarian cancer responds to re-treatment with carboplatin. She is now in a second remission. Which maintenance therapy is MOST beneficial?', '["Bevacizumab alone", "PARP inhibitor (e.g., Olaparib or Niraparib) maintenance therapy", "Tamoxifen", "No maintenance needed"]', 1, 'PARP inhibitors as maintenance therapy following platinum-sensitive response (especially in BRCA-mutant patients) significantly prolong progression-free survival. FDA-approved in this setting. (Comprehensive Gynecology; ACOG)'),

    (v_topic_id, '358: Which ovarian tumor is MOST associated with the triad of: bilateral masses, solid components, and markedly elevated CA-125 in a 35-year-old with a family history of colon and endometrial cancer?', '["High-grade serous carcinoma", "Endometrioid carcinoma (associated with Lynch Syndrome)", "Mucinous carcinoma", "Granulosa cell tumor"]', 1, 'Endometrioid ovarian carcinoma (and to a lesser extent clear cell) is associated with Lynch Syndrome (dMMR) and co-existing endometrial cancer. (Comprehensive Gynecology; Beckmann)'),

    (v_topic_id, '359: A "Call-Exner body" on ovarian pathology is the classic histological hallmark of which tumor?', '["Serous carcinoma", "Granulosa Cell Tumor", "Dysgerminoma", "Yolk Sac Tumor"]', 1, 'Small follicle-like structures (Call-Exner bodies) filled with eosinophilic material are the pathognomonic finding of Granulosa Cell Tumors. (Williams; Comprehensive Gynecology)'),

    (v_topic_id, '360: "Anti-Müllerian Hormone" (AMH) is a tumor marker for which ovarian tumor type?', '["Serous cystadenocarcinoma", "Granulosa Cell Tumor", "Mucinous cystadenoma", "Dysgerminoma"]', 1, 'AMH is produced by granulosa cells and serves as a useful marker for Granulosa Cell Tumors (sex cord-stromal), especially for monitoring recurrence. (Comprehensive Gynecology; Case Files OB/GYN)'),

    (v_topic_id, '361: A patient with Stage IC dysgerminoma (1 involved ovary, capsule rupture) who desires fertility. She undergoes unilateral salpingo-oophorectomy. What is the next step?', '["Hysterectomy and BSO", "BEP chemotherapy (3 cycles)", "Observation only — no adjuvant needed for Stage IA", "Radiation to the contralateral ovary"]', 1, 'Stage IC dysgerminoma (capsule rupture or positive washings) requires adjuvant BEP chemotherapy to prevent recurrence; Stage IA dysgerminoma can sometimes be observed. (ACOG; Comprehensive Gynecology)'),

    -- ===== GESTATIONAL TROPHOBLASTIC NEOPLASIA (GTN) — ADVANCED =====
    (v_topic_id, '362: A patient is treated with single-agent Methotrexate for low-risk GTN. After 2 cycles, hCG has plateaued (< 10% decline over 3 measurements). What is the NEXT step?', '["Continue Methotrexate", "Switch to single-agent Actinomycin-D (Act-D)", "Switch to multi-agent EMA-CO", "Hysterectomy"]', 1, 'Plateau in hCG with first-line single agent is treated by switching to the alternative single agent (MTX → Act-D or vice versa) before escalating to multi-agent regimens. (ACOG; Williams)'),

    (v_topic_id, '363: A patient completes treatment for Choriocarcinoma with EMA-CO chemotherapy. hCG is now zero. For how long should pregnancy be DEFERRED?', '["1 month", "6 months", "12 months after negative hCG", "5 years"]', 2, 'ACOG recommends deferring pregnancy for 12 months after achieving negative hCG to ensure complete remission monitoring and avoid confusion between rising hCG from relapse vs. normal pregnancy. (ACOG; Williams)'),

    (v_topic_id, '364: A woman has an "Invasive Mole" confirmed on imaging (myometrial invasion) after molar evacuation. hCG is rising. What distinguishes this from Choriocarcinoma?', '["Age of the patient", "Invasive mole retains chorionic villi on pathology (choriocarcinoma does not)", "hCG level", "Size of the uterus"]', 1, 'The key histological distinction: invasive mole contains identifiable chorionic villi; choriocarcinoma shows only trophoblastic proliferation without villi. (Williams; Comprehensive Gynecology)'),

    -- ===== VULVAR / VAGINAL — ADVANCED =====
    (v_topic_id, '365: A 72-year-old woman has a 3.5 cm vulvar SCC on the right labia majora, 2 cm from the midline. The lesion is clinically confined to the vulva (T2, no palpable nodes). What is the STANDARD surgical approach?', '["Wide local excision (WLE) only", "WLE with bilateral inguino-femoral lymphadenectomy (due to proximity to midline and tumor size > 2 cm)", "Radical vulvectomy with no lymph node dissection", "Radiation alone"]', 1, 'Tumors > 2 cm or with > 1 mm depth of invasion require lymph node assessment; lesions within 2 cm of the midline drain bilaterally, so bilateral groin dissection or bilateral SLN biopsy is required. (Beckmann; Comprehensive Gynecology)'),

    (v_topic_id, '366: A patient with vulvar melanoma (3 mm depth of invasion) undergoes wide local excision. What margins are required for adequate resection?', '["1 mm", "1 cm", "2 cm (similar to cutaneous melanoma > 2 mm Breslow thickness)", "3 cm"]', 2, 'Vulvar melanoma follows similar surgical margin principles to cutaneous melanoma based on Breslow depth; > 2 mm depth requires 2 cm margins. (Beckmann; Comprehensive Gynecology)'),

    (v_topic_id, '367: A 16-year-old girl presents with a grape-like polypoid mass protruding from the vagina. Biopsy reveals embryonal rhabdomyosarcoma. What is the PRIMARY treatment modality?', '["Radical hysterectomy and vaginectomy", "Multi-agent chemotherapy (VAC: Vincristine, Actinomycin-D, Cyclophosphamide) followed by limited surgery", "Radiation alone", "Observation"]', 1, 'Modern management of Sarcoma Botryoides uses multimodal therapy (chemotherapy first) to shrink the tumor and allow organ preservation, avoiding radical surgery in children. (Comprehensive Gynecology; Beckmann)'),

    -- ===== HIGH-YIELD INTEGRATION AND CLINICAL DECISION-MAKING =====
    (v_topic_id, '368: A 55-year-old woman has a right adnexal mass. Ultrasound shows a 7 cm cystic mass with 3 internal papillary projections and color Doppler shows low impedance flow. CA-125 is 280 U/mL. Using the IOTA (International Ovarian Tumor Analysis) criteria, this is most likely:', '["Benign — manage conservatively", "Malignant — refer to gynecologic oncologist for surgical management", "Infectious — treat with antibiotics", "Functional cyst — follow-up in 6 weeks"]', 1, 'IOTA criteria (including papillary projections, low impedance flow in postmenopausal women, and elevated CA-125) predict high risk of malignancy; referral to gynecologic oncology is mandatory. (ACOG; Comprehensive Gynecology)'),

    (v_topic_id, '369: A 30-year-old woman undergoes fertility-sparing surgery for Stage IA Grade 1 endometrial cancer (grade 1, superficial invasion). She is treated with a levonorgestrel-releasing IUD. EMB at 6 months shows complete response. When should she ATTEMPT pregnancy?', '["Immediately after negative biopsy", "After 12 months of sustained negative biopsies, then attempt conception promptly", "After menopause", "Never — she must have hysterectomy first"]', 1, 'Fertility-sparing management with progestins in young women with early low-grade endometrial cancer requires confirmed remission on biopsy, and prompt pregnancy attempt is recommended as definitive hysterectomy should follow completion of childbearing. (ACOG; Comprehensive Gynecology)'),

    (v_topic_id, '370: A patient with locally advanced cervical cancer (Stage IIIC2 — para-aortic node involvement) is undergoing chemoradiation. Which clinical trial-proven addition has recently improved outcomes in this setting?', '["Adding immunotherapy (Pembrolizumab) to concurrent chemoradiation (KEYNOTE-A18)", "Adding bevacizumab to surgery", "Adding tamoxifen to radiation", "Adding progestins"]', 0, 'The KEYNOTE-A18 trial demonstrated that adding pembrolizumab (anti-PD-1) to standard chemoradiation significantly improved progression-free survival in high-risk locally advanced cervical cancer, representing a new standard of care. (KEYNOTE-A18; Comprehensive Gynecology)');

    RAISE NOTICE 'SUCCESS: Batch 7 (336-370) MCQs for Gyn Malignancies registered.';
    RAISE NOTICE 'GRAND TOTAL MCQs FOR obgyn-malignancies: 370';
END $$;
COMMIT;
